-- Lösungswege für die Forderungskarte (ohne Punkte). Upsert, damit gespeicherte Forderungen ihren Verweis behalten.
insert into public.instrumente (id, thema_id, name, begruendung, evidenz, beleg_studie_url, ebene, entspricht, ki_entwurf, entwurf_herkunft, nebenwirkungen) values
  (9490, 32, 'Verstetigte Förderung für Clubs, Spielstätten und soziokulturelle Zentren (Land)', 'Dauerhafte Zuschüsse schließen die Budgetlücke kleiner Orte direkt; Fachnetzwerke nennen Förderung als zentrale Hilfe. Gegen Mieten- und Verdrängungsdruck wirkt Geld allein nur begrenzt.', 'belegt', 'https://liveurope.eu/node/18023', 'land', null, true, 'blind', null),
  (9491, 32, 'Zwischennutzung von Leerstand und öffentlichen Gebäuden für Kultur erleichtern (Land)', 'Schafft kurzfristig günstige Räume für Kultur, Erfahrungen aus vielen Städten liegen vor. Zwischennutzungen sind aber befristet und unsicher und ersetzen keine dauerhaften Orte.', 'gemischt', null, 'land', null, true, 'blind', null),
  (9492, 32, 'Kulturorte allgemein vor Verdrängung schützen, ohne konkretes Instrument (Land)', 'Benennt das Problem der Verdrängung, nennt aber kein Instrument, das Mieten oder konkurrierende Nutzungen beeinflusst; die Wirkung hängt von der späteren Ausgestaltung ab.', 'offen', null, 'land', null, true, 'blind', null),
  (9493, 32, 'Flächen für Clubs und Kulturorte planungsrechtlich sichern (Land)', 'Planerische Sicherung und frühe Berücksichtigung in Quartieren können Verdrängung und spätere Konflikte verhindern. Wichtige Teile des Planungsrechts liegen beim Bund, Umsetzung erfolgt kommunal und dauert.', 'gemischt', null, 'land', null, true, 'blind', null),
  (9494, 32, 'Gewerbemieten begrenzen und Gewerbemietende schützen per Bundesratsinitiative (Land)', 'Eine Begrenzung von Gewerbemieten setzt direkt an steigenden Mieten an; Wirkung im Gewerbe ist in Deutschland kaum untersucht. Das Land kann nur anstoßen, entscheiden muss der Bund.', 'offen', null, 'land', null, true, 'blind', null),
  (9495, 32, 'Genehmigungsverfahren und Zuständigkeiten für Veranstaltungen vereinfachen (Land)', 'Einfachere Verfahren senken Aufwand und Hürden für Veranstaltungen; an Schallkonflikten mit Anwohnenden ändern sie wenig.', 'offen', null, 'land', null, true, 'blind', null),
  (9496, 32, 'Vorrang bestehender Clubs bei Lärmkonflikten, Schallschutzpflicht für Neubauten (Land)', 'Das Agent-of-Change-Prinzip legt Schallschutz Neubauenden auf und wird in Großbritannien und Australien angewendet; Berichte zeigen aber uneinheitliche Anwendung, Wirkungsstudien fehlen. Lärmrecht liegt teils beim Bund.', 'gemischt', 'https://www.ioa.org.uk/news/Small-music-venues---noise-complaints-contributing-to-closures', 'land', null, true, 'blind', null),
  (9497, 32, 'Investitionsförderung für Sanierung, Technik, Schall- und Brandschutz von Kulturorten (Land)', 'Zuschüsse für Umbau, Technik und Brandschutz machen Gebäude für Veranstaltungen nutzbar und senken Investitionslast; Umfang und Zielgenauigkeit für kleine Orte bleiben offen.', 'offen', null, 'land', null, true, 'blind', null),
  (9498, 32, 'Einzelne Großimmobilien zu Kultur- und Veranstaltungsorten entwickeln (Land)', 'Schafft wenige große Veranstaltungsorte; kleinen Spielstätten und Clubs mit knappen Budgets hilft das kaum. Umbauten großer Bestandsbauten sind teuer und langwierig.', 'offen', null, 'land', null, true, 'blind', null),
  (9499, 32, 'Umbau von Handels- und Einkaufsimmobilien auch für Kulturnutzung (Land)', 'Kann zusätzliche Räume für Kultur schaffen, Kultur ist aber nur eine von mehreren Nutzungen; ob Räume bezahlbar und für Musikbetrieb geeignet sind, bleibt offen.', 'offen', null, 'land', null, true, 'blind', null),
  (9500, 32, 'Barrierefreien Umbau von Kulturorten fördern (Land)', 'Verbessert die Nutzbarkeit für das Publikum, berührt die Ursache (Gebäude nicht für Publikumsbetrieb ausgelegt) aber nur am Rand; Akustik und Kosten bleiben unberührt.', 'offen', null, 'land', null, true, 'blind', null),
  (9501, 32, 'Clubs als Kulturorte anerkennen und Förderrichtlinien für sie öffnen (Land)', 'Öffnet Clubs den Zugang zu Kulturförderung, schafft aber selbst keine zusätzlichen Mittel; Wirkung hängt von vorhandenen Budgets ab.', 'offen', null, 'land', null, true, 'blind', null),
  (9502, 32, 'Clubs im Bauplanungsrecht als Kulturorte einstufen und vor Verdrängung schützen (Bund)', 'Einstufung als Anlage für kulturelle Zwecke erweitert zulässige Standorte, der Bund ist zuständig. Planungsämter halten Konflikte aber nicht allein über Gebietskategorien für lösbar; Wirkungsbelege fehlen.', 'gemischt', 'https://www.evangelisch.de/inhalte/185975/08-05-2021/clubs-sind-kuenftig-kulturstaetten', 'bund', null, true, 'blind', null),
  (9503, 32, 'Gewerbemietrecht ändern, um Kulturorte vor Mietsteigerung und Verdrängung zu schützen (Bund)', 'Setzt direkt an steigenden Gewerbemieten an; Wirkung einer Gewerbemietbegrenzung ist kaum untersucht, Eingriffe in die Vertragsfreiheit sind rechtlich anspruchsvoll und umstritten.', 'offen', null, 'bund', null, true, 'blind', null)
