  (9513, 32, 11, 'MV', 'Dem Clubsterben entgegenwirken und mehr Club-Angebote, auch mobil im ländlichen Raum, unterstützen (ohne konkretes Instrument)', '{3201}', 9492, 1, 3, null, 'Benennt das Problem der Verdrängung, nennt aber kein Instrument, das Mieten oder konkurrierende Nutzungen beeinflusst; die Wirkung hängt von der späteren Ausgestaltung ab.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=129', null, 'offen', '2026-10-11', false, true, 'blind', null),
  (9514, 32, 11, 'ST', 'Gezielte Startförderungen für Clubs und kreative Orte auflegen', '{3203}', 9490, 2, 3, null, 'Dauerhafte Zuschüsse schließen die Budgetlücke kleiner Orte direkt; Fachnetzwerke nennen Förderung als zentrale Hilfe. Gegen Mieten- und Verdrängungsdruck wirkt Geld allein nur begrenzt.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=82', 'https://liveurope.eu/node/18023', 'belegt', '2026-10-11', false, true, 'blind', null),
