  (9516, 32, 12, 'BE', 'Eine neue Förderung für Clubs und Spielstätten einführen.', '{3203}', 9490, 2, 3, null, 'Dauerhafte Zuschüsse schließen die Budgetlücke kleiner Orte direkt; Fachnetzwerke nennen Förderung als zentrale Hilfe. Gegen Mieten- und Verdrängungsdruck wirkt Geld allein nur begrenzt.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=11', 'https://liveurope.eu/node/18023', 'belegt', '2026-10-11', false, true, 'blind', null),
  (9517, 32, 12, 'BE', 'Leerstehende Ladenflächen für Kultur- und andere Angebote zwischennutzen und dafür Genehmigungen vereinfachen.', '{3201}', 9491, 2, 3, null, 'Schafft kurzfristig günstige Räume für Kultur, Erfahrungen aus vielen Städten liegen vor. Zwischennutzungen sind aber befristet und unsicher und ersetzen keine dauerhaften Orte.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=19', null, 'gemischt', '2026-10-11', false, true, 'blind', null),
  (9518, 32, 12, 'BE', 'Sich auf Bundesebene für gesetzliche Regelungen zu bezahlbaren Gewerbemieten einsetzen, um Gewerbe und Kultur in den Kiezen vor Verdrängung zu schützen.', '{3201}', 9494, 2, 1, null, 'Eine Begrenzung von Gewerbemieten setzt direkt an steigenden Mieten an; Wirkung im Gewerbe ist in Deutschland kaum untersucht. Das Land kann nur anstoßen, entscheiden muss der Bund.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=13', null, 'offen', '2026-10-11', false, true, 'blind', null),
  (9519, 32, 12, 'BE', 'Das ICC zu einem Zentrum für Kultur, Kreativwirtschaft und Großveranstaltungen umbauen.', '{3204}', 9498, 1, 2, null, 'Schafft wenige große Veranstaltungsorte; kleinen Spielstätten und Clubs mit knappen Budgets hilft das kaum. Umbauten großer Bestandsbauten sind teuer und langwierig.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=15', null, 'offen', '2026-10-11', false, true, 'blind', null),
  (9520, 32, 12, 'BE', 'Stärkere Kooperation zwischen Produktion und Präsentation von Kunst ermöglichen, mit gemeinschaftlich nutzbaren Infrastrukturen wie Ateliers und Proberäumen.', '{3203}', null, 1, 3, null, 'Gemeinsam nutzbare Proberäume und Ateliers verbessern die Raumlage für Kulturschaffende; Umfang und Finanzierung sind unbestimmt.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=14', null, 'offen', '2026-10-11', false, true, 'blind', null),
  (9521, 32, 12, 'MV', 'Förderung von Dritten Orten wie soziokulturellen Zentren als Orte lokaler Begegnung und Vernetzung', '{3203}', 9490, 2, 3, null, 'Dauerhafte Zuschüsse schließen die Budgetlücke kleiner Orte direkt; Fachnetzwerke nennen Förderung als zentrale Hilfe. Gegen Mieten- und Verdrängungsdruck wirkt Geld allein nur begrenzt.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=80', 'https://liveurope.eu/node/18023', 'belegt', '2026-10-11', false, true, 'blind', null),
  (9522, 32, 12, 'ST', 'Clubs als Kulturorte anerkennen und schützen', '{3201}', 9492, 1, 3, null, 'Benennt das Problem der Verdrängung, nennt aber kein Instrument, das Mieten oder konkurrierende Nutzungen beeinflusst; die Wirkung hängt von der späteren Ausgestaltung ab.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=39', null, 'offen', '2026-10-11', false, true, 'blind', null),
  (9523, 32, 12, 'ST', 'Gast- und Spielstättenförderung für die freie Theaterszene und Kulturhäuser ohne eigenes Ensemble auf den Weg bringen', '{3203}', 9490, 2, 3, null, 'Dauerhafte Zuschüsse schließen die Budgetlücke kleiner Orte direkt; Fachnetzwerke nennen Förderung als zentrale Hilfe. Gegen Mieten- und Verdrängungsdruck wirkt Geld allein nur begrenzt.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=39', 'https://liveurope.eu/node/18023', 'belegt', '2026-10-11', false, true, 'blind', null),
  (9524, 32, 12, 'ST', 'Zuständigkeiten für Sicherheitskonzepte und Schutzmaßnahmen bei Großveranstaltungen gesetzlich klar regeln', '{3202}', 9495, 1, 3, null, 'Einfachere Verfahren senken Aufwand und Hürden für Veranstaltungen; an Schallkonflikten mit Anwohnenden ändern sie wenig.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=30', null, 'offen', '2026-10-11', false, true, 'blind', null),
  (9525, 32, 13, null, 'Gewerbemietrecht ändern, damit Clubs und vergleichbare Kulturorte vor Verdrängung geschützt sind', '{3201}', 9503, 2, 2, null, 'Setzt direkt an steigenden Gewerbemieten an; Wirkung einer Gewerbemietbegrenzung ist kaum untersucht, Eingriffe in die Vertragsfreiheit sind rechtlich anspruchsvoll und umstritten.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=105', null, 'offen', '2026-10-11', false, true, 'blind', null),
  (9526, 32, 13, null, 'Baurecht ändern, um Rahmenbedingungen für Clubs und Livemusikstätten zu verbessern', '{3201}', 9502, 2, 3, null, 'Einstufung als Anlage für kulturelle Zwecke erweitert zulässige Standorte, der Bund ist zuständig. Planungsämter halten Konflikte aber nicht allein über Gebietskategorien für lösbar; Wirkungsbelege fehlen.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=124', 'https://www.evangelisch.de/inhalte/185975/08-05-2021/clubs-sind-kuenftig-kulturstaetten', 'gemischt', '2026-10-11', false, true, 'blind', null),
  (9527, 32, 13, null, 'Lärmschutz ändern, um Rahmenbedingungen für Clubs und Livemusikstätten zu verbessern', '{3202}', null, 2, 3, null, 'Änderungen im Lärmschutzrecht (etwa TA Lärm) können Konflikte zwischen Clubs und Anwohnenden entschärfen, der Bund ist zuständig. Inhalt der Änderung unbestimmt, Schutz der Anwohnenden muss gewahrt bleiben.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=124', null, 'offen', '2026-10-11', false, true, 'blind', null),
  (9528, 32, 13, null, 'Förderung von Schallschutzmaßnahmen für Kulturorte ausbauen', '{3202}', null, 2, 3, null, 'Förderung von Schallschutz setzt direkt an Lärmkonflikten an, der Bund hat bereits ein solches Programm aufgelegt. Eine Wirkungsevaluation fehlt, Umfang offen.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=124', null, 'offen', '2026-10-11', false, true, 'blind', null),
  (9529, 32, 13, null, 'Kultur-Investitionsprogramme des Bundes für Einrichtungen der freien Szene und Popkultur stärker öffnen', '{3203}', null, 2, 3, null, 'Öffnet bestehende Bundes-Investitionsprogramme für freie Szene und Popkultur und entlastet so kleine Orte bei Investitionen; Umfang der zusätzlichen Mittel ist offen.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=125', null, 'offen', '2026-10-11', false, true, 'blind', null),
  (9530, 32, 13, 'BE', 'Verbindliche Quote für Kultur- und Kreativräume in neuen Stadtquartieren', '{3201}', 9493, 2, 2, null, 'Planerische Sicherung und frühe Berücksichtigung in Quartieren können Verdrängung und spätere Konflikte verhindern. Wichtige Teile des Planungsrechts liegen beim Bund, Umsetzung erfolgt kommunal und dauert.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=60', null, 'gemischt', '2026-10-11', false, true, 'blind', null),
  (9531, 32, 13, 'BE', 'Milieuschutz auch für Gewerbemietende einführen', '{3201}', 9494, 2, 1, null, 'Eine Begrenzung von Gewerbemieten setzt direkt an steigenden Mieten an; Wirkung im Gewerbe ist in Deutschland kaum untersucht. Das Land kann nur anstoßen, entscheiden muss der Bund.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=101', null, 'offen', '2026-10-11', false, true, 'blind', null),
  (9532, 32, 13, 'BE', 'Härtefallregelung bei der Grundsteuer für Clubs und kulturelle Einrichtungen', '{3201}', null, 1, 2, null, 'Eine Härtefallregel senkt Kostensteigerungen bei der Grundsteuer für Clubs; der Anteil an den Gesamtkosten ist klein, rechtlich muss die Regel gleichheitskonform ausgestaltet werden.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=47', null, 'offen', '2026-10-11', false, true, 'blind', null),
  (9533, 32, 13, 'BE', 'Aktionsplan gegen Verdrängung queerer und zivilgesellschaftlicher Orte einschließlich Kulturorten', '{3201}', 9492, 1, 3, null, 'Benennt das Problem der Verdrängung, nennt aber kein Instrument, das Mieten oder konkurrierende Nutzungen beeinflusst; die Wirkung hängt von der späteren Ausgestaltung ab.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=150', null, 'offen', '2026-10-11', false, true, 'blind', null),
  (9534, 32, 13, 'BE', 'Bund: Gewerbemietpreisbremse, Mietspiegel und Kündigungsschutz für Gewerbemietende unterstützen', '{3201}', 9494, 2, 1, null, 'Eine Begrenzung von Gewerbemieten setzt direkt an steigenden Mieten an; Wirkung im Gewerbe ist in Deutschland kaum untersucht. Das Land kann nur anstoßen, entscheiden muss der Bund.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=101', null, 'offen', '2026-10-11', false, true, 'blind', null),
  (9535, 32, 13, 'BE', 'Vereinfachte Genehmigungsverfahren und Lärmschutz-Reform (Bund) für Clubs und kleine Musikspielstätten', '{3202}', 9495, 1, 3, null, 'Einfachere Verfahren senken Aufwand und Hürden für Veranstaltungen; an Schallkonflikten mit Anwohnenden ändern sie wenig.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=69', null, 'offen', '2026-10-11', false, true, 'blind', null),
  (9536, 32, 13, 'BE', 'Notfallfonds für akut bedrohte Orte der Clubkultur einrichten', '{3203}', null, 1, 3, null, 'Ein Notfallfonds kann akute Schließungen abwenden, lindert aber nur Folgen und ändert die dauerhaft knappen Budgets nicht.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=70', null, 'offen', '2026-10-11', false, true, 'blind', null),
  (9537, 32, 13, 'BE', 'Förderung des barrierefreien Umbaus von Kulturstätten', '{3204}', 9500, 1, 3, null, 'Verbessert die Nutzbarkeit für das Publikum, berührt die Ursache (Gebäude nicht für Publikumsbetrieb ausgelegt) aber nur am Rand; Akustik und Kosten bleiben unberührt.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=218', null, 'offen', '2026-10-11', false, true, 'blind', null),
  (9538, 32, 13, 'BE', 'Öffentliche Investitionen in die Ausstattung öffentlicher Veranstaltungsorte', '{3204}', 9497, 2, 3, null, 'Zuschüsse für Umbau, Technik und Brandschutz machen Gebäude für Veranstaltungen nutzbar und senken Investitionslast; Umfang und Zielgenauigkeit für kleine Orte bleiben offen.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=165', null, 'offen', '2026-10-11', false, true, 'blind', null),
  (9539, 32, 13, 'BE', 'Einkaufszentren zu multifunktionalen Orten mit Raum für Kultur weiterentwickeln', '{3204}', 9499, 1, 2, null, 'Kann zusätzliche Räume für Kultur schaffen, Kultur ist aber nur eine von mehreren Nutzungen; ob Räume bezahlbar und für Musikbetrieb geeignet sind, bleibt offen.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=101', null, 'offen', '2026-10-11', false, true, 'blind', null),
  (9540, 32, 13, 'BE', 'Orte wie Tempelhofer Vorfeld, Straße des 17. Juni und Waldbühne für Großveranstaltungen weiterentwickeln', '{3204}', 9498, 1, 2, null, 'Schafft wenige große Veranstaltungsorte; kleinen Spielstätten und Clubs mit knappen Budgets hilft das kaum. Umbauten großer Bestandsbauten sind teuer und langwierig.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=68', null, 'offen', '2026-10-11', false, true, 'blind', null),
  (9541, 32, 13, 'MV', 'Eigenmittel- und Liquiditätsfonds, der soziokulturellen Begegnungs- und Bildungsorten beim Einwerben von Fördermitteln hilft', '{3203}', 9490, 2, 3, null, 'Dauerhafte Zuschüsse schließen die Budgetlücke kleiner Orte direkt; Fachnetzwerke nennen Förderung als zentrale Hilfe. Gegen Mieten- und Verdrängungsdruck wirkt Geld allein nur begrenzt.', 'https://gruene-mv.de/?wpdmdl=33772#page=96', 'https://liveurope.eu/node/18023', 'belegt', '2026-10-11', false, true, 'blind', null),
  (9542, 32, 13, 'ST', 'Landesprogramm Soziokultur mit mindestens 500.000 Euro für soziokulturelle Zentren', '{3203}', 9490, 2, 3, null, 'Dauerhafte Zuschüsse schließen die Budgetlücke kleiner Orte direkt; Fachnetzwerke nennen Förderung als zentrale Hilfe. Gegen Mieten- und Verdrängungsdruck wirkt Geld allein nur begrenzt.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=70', 'https://liveurope.eu/node/18023', 'belegt', '2026-10-11', false, true, 'blind', null),
  (9543, 32, 13, 'ST', 'Förderprogramm für Clubs und Musikspielstätten: Basisförderung für feste Spielstätten bei Sanierung und Betrieb, auch für Technik, Lärm- und Brandschutz', '{3204,3202}', 9497, 2, 3, null, 'Zuschüsse für Umbau, Technik und Brandschutz machen Gebäude für Veranstaltungen nutzbar und senken Investitionslast; Umfang und Zielgenauigkeit für kleine Orte bleiben offen.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=70', null, 'offen', '2026-10-11', false, true, 'blind', null),
  (9544, 32, 14, 'BE', 'Clubs, Musikspielstätten und Open-Air-Formate frühzeitig in Stadtentwicklung, Quartiersplanung und Genehmigung berücksichtigen, um gewachsene Kulturorte zu sichern', '{3201,3202}', 9493, 2, 2, null, 'Planerische Sicherung und frühe Berücksichtigung in Quartieren können Verdrängung und spätere Konflikte verhindern. Wichtige Teile des Planungsrechts liegen beim Bund, Umsetzung erfolgt kommunal und dauert.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=110', null, 'gemischt', '2026-10-11', false, true, 'blind', null),
  (9545, 32, 14, 'BE', 'Wer neu in die Nachbarschaft von Clubs baut, muss selbst für ausreichenden Schallschutz sorgen (Agent-of-Change-Prinzip)', '{3202}', 9496, 2, 2, null, 'Das Agent-of-Change-Prinzip legt Schallschutz Neubauenden auf und wird in Großbritannien und Australien angewendet; Berichte zeigen aber uneinheitliche Anwendung, Wirkungsstudien fehlen. Lärmrecht liegt teils beim Bund.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=34', 'https://www.ioa.org.uk/news/Small-music-venues---noise-complaints-contributing-to-closures', 'gemischt', '2026-10-11', false, true, 'blind', null),
  (9546, 32, 14, 'BE', 'Zwischennutzung leerstehender Gebäude, temporäre Veranstaltungsflächen und Open-Air-Angebote erleichtern', '{3201}', 9491, 2, 3, null, 'Schafft kurzfristig günstige Räume für Kultur, Erfahrungen aus vielen Städten liegen vor. Zwischennutzungen sind aber befristet und unsicher und ersetzen keine dauerhaften Orte.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=34', null, 'gemischt', '2026-10-11', false, true, 'blind', null),
  (9547, 32, 14, 'BE', 'Keine pauschale Sperrstunde und keine Tanzverbote an Feiertagen für Clubs', '{3202}', null, 1, 3, null, 'Verzicht auf Sperrstunde und Tanzverbote vermeidet zusätzliche Auflagen für Clubs; Schallkonflikte mit Anwohnenden löst das nicht.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=111', null, 'offen', '2026-10-11', false, true, 'blind', null),
  (9548, 32, 14, 'BE', 'Konflikte zwischen Anwohnenden, Bezirken und Clubbetreibenden durch frühzeitige Mediation lösen, etwa über das Büro des Nachtlebens', '{3202}', null, 1, 3, null, 'Frühe Mediation kann Lärmkonflikte entschärfen, bevor Auflagen oder Schließungen drohen; an der Schallursache selbst ändert sie nichts, Wirkungsbelege fehlen.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=111', null, 'offen', '2026-10-11', false, true, 'blind', null),
  (9549, 32, 14, 'BE', 'Bei Konflikten zwischen alten Clubrechten und neuen Ansprüchen von Anwohnenden sollen die alten Rechte vorgehen', '{3202}', 9496, 2, 2, null, 'Das Agent-of-Change-Prinzip legt Schallschutz Neubauenden auf und wird in Großbritannien und Australien angewendet; Berichte zeigen aber uneinheitliche Anwendung, Wirkungsstudien fehlen. Lärmrecht liegt teils beim Bund.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=110', 'https://www.ioa.org.uk/news/Small-music-venues---noise-complaints-contributing-to-closures', 'gemischt', '2026-10-11', false, true, 'blind', null),
  (9550, 32, 14, 'BE', 'Clubs als Kulturorte anerkennen und so besseren Zugang zu Kulturförderung ermöglichen', '{3203}', 9501, 1, 3, null, 'Öffnet Clubs den Zugang zu Kulturförderung, schafft aber selbst keine zusätzlichen Mittel; Wirkung hängt von vorhandenen Budgets ab.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=34', null, 'offen', '2026-10-11', false, true, 'blind', null),
  (9551, 32, 14, 'MV', 'Kommunale Genehmigungs- und Antragsverfahren für Veranstaltungen vereinfachen, digitalisieren und beschleunigen', '{3202}', 9495, 1, 3, null, 'Einfachere Verfahren senken Aufwand und Hürden für Veranstaltungen; an Schallkonflikten mit Anwohnenden ändern sie wenig.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=122', null, 'offen', '2026-10-11', false, true, 'blind', null),
  (9552, 32, 14, 'ST', 'Schulgebäude außerhalb des Unterrichts für Vereine und Kulturangebote öffnen', '{3201}', 9491, 2, 3, null, 'Schafft kurzfristig günstige Räume für Kultur, Erfahrungen aus vielen Städten liegen vor. Zwischennutzungen sind aber befristet und unsicher und ersetzen keine dauerhaften Orte.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=29', null, 'gemischt', '2026-10-11', false, true, 'blind', null),
  (9553, 32, 15, 'BE', 'Kulturarbeit in Außenbezirken verbessern; zentraler Aspekt ist die Bereitstellung von Räumlichkeiten', '{3201}', 9491, 2, 3, null, 'Schafft kurzfristig günstige Räume für Kultur, Erfahrungen aus vielen Städten liegen vor. Zwischennutzungen sind aber befristet und unsicher und ersetzen keine dauerhaften Orte.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=89', null, 'gemischt', '2026-10-11', false, true, 'blind', null),
  (9554, 32, 15, 'ST', 'Kulturprojekte bis hin zu Kleinkunstbühnen sollen eine Stiftung zur Unterstützung erhalten.', '{3203}', null, 1, 2, null, 'Eine Stiftung kann auch Kleinkunstbühnen unterstützen; der Bezug zu Spielstätten ist schmal, Kapital und Förderumfang sind offen.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=193', null, 'offen', '2026-10-11', false, true, 'blind', null),
  (9555, 32, 16, null, 'Queere Clubs und Orte vor Wuchermieten und Kürzungen staatlicher Zuschüsse schützen', '{3201,3203}', null, 1, 2, null, 'Benennt Mieten und Zuschusskürzungen als Gefahr für queere Clubs, nennt aber kein Instrument; Mietschutz bräuchte Änderungen im Gewerbemietrecht.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=47', null, 'offen', '2026-10-11', false, true, 'blind', null),
  (9556, 32, 16, null, 'Bund schafft die Voraussetzung, dass Länder und Kommunen Mietendeckel für Kleingewerbe und kulturelle Einrichtungen einführen können', '{3201}', 9503, 2, 2, null, 'Setzt direkt an steigenden Gewerbemieten an; Wirkung einer Gewerbemietbegrenzung ist kaum untersucht, Eingriffe in die Vertragsfreiheit sind rechtlich anspruchsvoll und umstritten.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=8', null, 'offen', '2026-10-11', false, true, 'blind', null),
  (9557, 32, 16, null, 'Bundesregeln so ändern, dass Stadtplanung Freiräume für Clubkultur berücksichtigen kann', '{3201}', 9502, 2, 3, null, 'Einstufung als Anlage für kulturelle Zwecke erweitert zulässige Standorte, der Bund ist zuständig. Planungsämter halten Konflikte aber nicht allein über Gebietskategorien für lösbar; Wirkungsbelege fehlen.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=45', 'https://www.evangelisch.de/inhalte/185975/08-05-2021/clubs-sind-kuenftig-kulturstaetten', 'gemischt', '2026-10-11', false, true, 'blind', null),
  (9558, 32, 16, null, 'Kulturförderung zur Pflichtaufgabe machen und Länder und Kommunen so ausstatten, dass sie gemeinnützige Kultur- und Veranstaltungsstätten verlässlich unterstützen können', '{3203}', null, 2, 1, null, 'Bessere Ausstattung von Ländern und Kommunen kann verlässliche Förderung von Veranstaltungsstätten sichern. Eine Pflichtaufgabe Kultur bräuchte Länderrecht oder Grundgesetzänderung; Finanzierung ungeklärt.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=55', null, 'offen', '2026-10-11', false, true, 'blind', null),
  (9559, 32, 16, 'BE', 'Gewerbemieten per Gesetz dauerhaft begrenzen; Vorstoß über den Bundesrat', '{3201}', 9494, 2, 1, null, 'Eine Begrenzung von Gewerbemieten setzt direkt an steigenden Mieten an; Wirkung im Gewerbe ist in Deutschland kaum untersucht. Das Land kann nur anstoßen, entscheiden muss der Bund.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=89', null, 'offen', '2026-10-11', false, true, 'blind', null),
  (9560, 32, 16, 'BE', 'Clubs im Baugesetzbuch als Kultureinrichtungen verankern (Bundesebene)', '{3201}', null, 2, 1, null, 'Die Einstufung von Clubs als Kultureinrichtungen im Baurecht erweitert zulässige Standorte; das Land kann sie nur beim Bund anstoßen.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=237', 'https://www.evangelisch.de/inhalte/185975/08-05-2021/clubs-sind-kuenftig-kulturstaetten', 'gemischt', '2026-10-11', false, true, 'blind', null),
  (9561, 32, 16, 'BE', 'Kulturelle Nutzung leer stehender Immobilien erleichtern und Zwischennutzungen ausweiten', '{3201}', 9491, 2, 3, null, 'Schafft kurzfristig günstige Räume für Kultur, Erfahrungen aus vielen Städten liegen vor. Zwischennutzungen sind aber befristet und unsicher und ersetzen keine dauerhaften Orte.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=238', null, 'gemischt', '2026-10-11', false, true, 'blind', null),
  (9562, 32, 16, 'BE', 'Landesförderung für Spielstätten (Clubs), die gesellschaftspolitisches Engagement würdigt', '{3203}', 9490, 2, 3, null, 'Dauerhafte Zuschüsse schließen die Budgetlücke kleiner Orte direkt; Fachnetzwerke nennen Förderung als zentrale Hilfe. Gegen Mieten- und Verdrängungsdruck wirkt Geld allein nur begrenzt.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=237', 'https://liveurope.eu/node/18023', 'belegt', '2026-10-11', false, true, 'blind', null),
  (9563, 32, 16, 'BE', 'Schallschutzfonds ausbauen und Genehmigungsverfahren für Veranstaltungen vereinfachen (Land)', '{3202}', null, 2, 3, null, 'Ein Schallschutzfonds finanziert Dämmung direkt an der Konfliktursache, hohe Antragszahlen zeigen Bedarf. Eine Wirkungsevaluation fehlt, die Mittel reichen meist nur für einen Teil der Orte.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=237', null, 'offen', '2026-10-11', false, true, 'blind', null),
  (9564, 32, 16, 'BE', 'Nutzung öffentlicher Räume für unkommerzielle Freiluftveranstaltungen deutlich erleichtern', '{3202}', 9495, 1, 3, null, 'Einfachere Verfahren senken Aufwand und Hürden für Veranstaltungen; an Schallkonflikten mit Anwohnenden ändern sie wenig.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=237', null, 'offen', '2026-10-11', false, true, 'blind', null),
  (9565, 32, 16, 'BE', 'Lärmschutzreform auf Bundesebene', '{3202}', null, 2, 1, null, 'Eine Lärmschutzreform könnte Konflikte zwischen Clubs und Anwohnenden entschärfen; das Land kann sie nur beim Bund anstoßen, Inhalt bleibt offen.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=237', null, 'offen', '2026-10-11', false, true, 'blind', null),
  (9566, 32, 16, 'MV', 'Kulturorte vor Verdrängung schützen und einen baurechtlichen Bestandsschutz für Kulturorte einführen.', '{3201}', 9493, 2, 2, null, 'Planerische Sicherung und frühe Berücksichtigung in Quartieren können Verdrängung und spätere Konflikte verhindern. Wichtige Teile des Planungsrechts liegen beim Bund, Umsetzung erfolgt kommunal und dauert.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=27', null, 'gemischt', '2026-10-11', false, true, 'blind', null),
  (9567, 32, 16, 'MV', 'Nutzung von Leerständen und öffentlichen Gebäuden für Kultur fördern.', '{3201}', 9491, 2, 3, null, 'Schafft kurzfristig günstige Räume für Kultur, Erfahrungen aus vielen Städten liegen vor. Zwischennutzungen sind aber befristet und unsicher und ersetzen keine dauerhaften Orte.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=27', null, 'gemischt', '2026-10-11', false, true, 'blind', null),
  (9568, 32, 16, 'MV', 'Selbstverwaltete und freie Kulturorte unterstützen.', '{3203}', null, 1, 3, null, 'Zielt auf selbstverwaltete Kulturorte mit kleinen Budgets, nennt aber weder Instrument noch Umfang der Unterstützung.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=27', null, 'offen', '2026-10-11', false, true, 'blind', null),
  (9569, 32, 16, 'MV', 'Bauliche Barrieren bei Kunst und Kultur abbauen (Grenzfall zu Umbau von Veranstaltungsorten).', '{3204}', 9500, 1, 3, null, 'Verbessert die Nutzbarkeit für das Publikum, berührt die Ursache (Gebäude nicht für Publikumsbetrieb ausgelegt) aber nur am Rand; Akustik und Kosten bleiben unberührt.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=26', null, 'offen', '2026-10-11', false, true, 'blind', null),
  (9570, 32, 16, 'ST', 'Verstetigte Landesförderung für Klubs und Musikspielstätten, um das Klubsterben zu bekämpfen', '{3203}', 9490, 2, 3, null, 'Dauerhafte Zuschüsse schließen die Budgetlücke kleiner Orte direkt; Fachnetzwerke nennen Förderung als zentrale Hilfe. Gegen Mieten- und Verdrängungsdruck wirkt Geld allein nur begrenzt.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=71', 'https://liveurope.eu/node/18023', 'belegt', '2026-10-11', false, true, 'blind', null),
  (9571, 32, 17, 'BE', 'Städtischer Kurator stellt freien Kunstschaffenden Orte und Räume im Stadtraum zeitlich begrenzt für Projekte zur Verfügung', '{3201}', 9491, 2, 3, null, 'Schafft kurzfristig günstige Räume für Kultur, Erfahrungen aus vielen Städten liegen vor. Zwischennutzungen sind aber befristet und unsicher und ersetzen keine dauerhaften Orte.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=20', null, 'gemischt', '2026-10-11', false, true, 'blind', null),
  (9572, 32, 17, 'BE', 'Möglichst viele noch verbleibende nichtkommerzielle Räume für Kunst und Kulturerfahrung sichern', '{3201}', 9492, 1, 3, null, 'Benennt das Problem der Verdrängung, nennt aber kein Instrument, das Mieten oder konkurrierende Nutzungen beeinflusst; die Wirkung hängt von der späteren Ausgestaltung ab.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=20', null, 'offen', '2026-10-11', false, true, 'blind', null),
  (9573, 32, 17, 'MV', 'Stärkung und Modernisierung von Spielstätten und soziokulturellen Zentren als Kulturorte', '{3203,3204}', 9490, 2, 3, null, 'Dauerhafte Zuschüsse schließen die Budgetlücke kleiner Orte direkt; Fachnetzwerke nennen Förderung als zentrale Hilfe. Gegen Mieten- und Verdrängungsdruck wirkt Geld allein nur begrenzt.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=54', 'https://liveurope.eu/node/18023', 'belegt', '2026-10-11', false, true, 'blind', null),
  (9574, 32, 17, 'ST', 'Institutionelle Förderung von Kulturorten ausweiten und verstetigen, vor allem für kleine und mittlere Einrichtungen im ländlichen Raum; soziokulturelle Zentren dauerhaft finanziell sichern', '{3203}', 9490, 2, 3, null, 'Dauerhafte Zuschüsse schließen die Budgetlücke kleiner Orte direkt; Fachnetzwerke nennen Förderung als zentrale Hilfe. Gegen Mieten- und Verdrängungsdruck wirkt Geld allein nur begrenzt.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=40', 'https://liveurope.eu/node/18023', 'belegt', '2026-10-11', false, true, 'blind', null);

